}
class _ProductSelectionSheetState extends State<ProductSelectionSheet>{
  late List<Map<String,dynamic>> options;
  final selected=<String,dynamic>{};
  int? variantId;int qty=1;bool saving=false;
  @override void initState(){super.initState();options=((widget.data['options']as List?)??const[]).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
    final vs=((widget.data['variants']as List?)??const[]).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
    variantId=vs.isEmpty?null:int.tryParse(pfText(vs.first['id']));
    for(final o in options){final vals=((o['values']as List?)??const[]).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();if(vals.isNotEmpty)_choose(o,vals.first,vs,false);}
  }
  void _choose(Map<String,dynamic> o,Map<String,dynamic> v,List<Map<String,dynamic>> vs,[bool notify=true]){
    final name=pfText(o['name'],'اختيار');final label=pfText(v['label']);if(label.isEmpty)return;selected[name]=label;
    final cid=v['color_id']==null?null:int.tryParse(v['color_id'].toString()),sid=v['size_id']==null?null:int.tryParse(v['size_id'].toString());
    for(final row in vs){final rc=row['color_id']==null?null:int.tryParse(row['color_id'].toString()),rs=row['size_id']==null?null:int.tryParse(row['size_id'].toString());if(cid!=null&&rc!=cid)continue;if(sid!=null&&rs!=sid)continue;variantId=int.tryParse(pfText(row['id']));break;}
    if(notify)setState((){});
  }
  Future<void>confirm()async{if(variantId==null)return;setState(()=>saving=true);try{await widget.onConfirm(variantId!,qty,Map<String,dynamic>.from(selected));if(mounted)Navigator.pop(context,true);}catch(e){if(mounted){setState(()=>saving=false);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(pfText(e))))}}}
