    final vs=((widget.data['variants']as List?)??const[]).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
    final p=widget.data['product']is Map?Map<String,dynamic>.from(widget.data['product']):<String,dynamic>{};
    return SafeArea(child:Directionality(textDirection:TextDirection.rtl,child:Padding(padding:EdgeInsets.fromLTRB(12,10,12,MediaQuery.viewInsetsOf(context).bottom+14),child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[
      Center(child:Container(width:38,height:4,decoration:BoxDecoration(color:const Color(0xFFD0D0D0),borderRadius:BorderRadius.circular(8)))),
      const SizedBox(height:9),const Text('تأكيد المنتج قبل الإضافة',textAlign:TextAlign.center,style:TextStyle(fontSize:17,fontWeight:FontWeight.w900)),
      const SizedBox(height:5),Text(pfText(p['name'],'المنتج'),textAlign:TextAlign.center,style:const TextStyle(fontSize:11,fontWeight:FontWeight.w700)),const SizedBox(height:11),
      ...options.map((o){final vals=((o['values']as List?)??const[]).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();final cur=pfText(selected[pfText(o['name'],'اختيار')]);return Padding(padding:const EdgeInsets.only(bottom:10),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(pfText(o['name'],'اختيار'),style:const TextStyle(fontSize:11,fontWeight:FontWeight.w900)),const SizedBox(height:5),Wrap(spacing:6,runSpacing:5,children:vals.map((v)=>ChoiceChip(label:Text(pfText(v['label']),style:const TextStyle(fontSize:9)),selected:cur==pfText(v['label']),onSelected:saving?null:(_)=>_choose(o,v,vs))).toList())]));}),
      Container(padding:const EdgeInsets.all(10),decoration:BoxDecoration(color:const Color(0xFFF7F7F7),borderRadius:BorderRadius.circular(10)),child:Row(children:[const Expanded(child:Text('الكمية',style:TextStyle(fontSize:11,fontWeight:FontWeight.w900))),_q(Icons.remove,qty>1&&!saving?()=>setState(()=>qty--):null),Padding(padding:const EdgeInsets.symmetric(horizontal:14),child:Text(qty.toString(),style:const TextStyle(fontWeight:FontWeight.w900,fontSize:14))),_q(Icons.add,!saving?()=>setState(()=>qty++):null)])),
      if(selected.isNotEmpty)Padding(padding:const EdgeInsets.only(top:7),child:Wrap(spacing:5,children:selected.entries.map((e)=>Chip(label:Text(e.key+': '+pfText(e.value),style:const TextStyle(fontSize:8.5)))).toList())),
      const SizedBox(height:10),SizedBox(height:46,child:FilledButton(onPressed:saving||variantId==null?null:confirm,style:FilledButton.styleFrom(backgroundColor:Colors.black),child:saving?const CircularProgressIndicator(color:Colors.white):const Text('تأكيد وإضافة إلى عربة التسوق',style:TextStyle(fontSize:10.5,fontWeight:FontWeight.w900)))),
    ]))));
  }
  Widget _q(IconData i,VoidCallback?f)=>InkWell(onTap:f,child:Container(width:32,height:32,alignment:Alignment.center,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(6),border:Border.all(color:const Color(0xFFD8D8D8))),child:Icon(i,size:15)));
