    const SizedBox(height:8),FilledButton.icon(onPressed:()async{final d=await api.newConversation();final raw=d['item'];final id=raw is Map?int.tryParse(pfText(raw['id'])):null;if(id!=null){await load();await openChat(id);}},icon:const Icon(Icons.add_comment_outlined),label:const Text('بدء محادثة')),
    const SizedBox(height:7),...convs.map((c)=>Container(margin:const EdgeInsets.only(bottom:6),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(10)),child:ListTile(leading:CircleAvatar(child:Icon(pfText(c['order_id']).isEmpty?Icons.support_agent:Icons.shopping_bag_outlined,size:18)),title:Text(pfText(c['subject'],'خدمة العملاء'),style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900)),subtitle:Text(pfText(c['status'],'مفتوحة'),style:const TextStyle(fontSize:8,color:ClientTheme.muted)),onTap:()=>openChat(int.tryParse(pfText(c['id']))??0)))),
