    Container(color:Colors.white,padding:const EdgeInsets.fromLTRB(8,6,8,6),child:Column(children:[if(files.isNotEmpty)Align(alignment:Alignment.centerRight,child:Wrap(spacing:4,children:files.map((f)=>Chip(onDeleted:sending?null:()=>setState(()=>files.remove(f)),label:Text(f.name,style:const TextStyle(fontSize:7)))).toList())),Row(children:[IconButton(onPressed:sending?null:pick,icon:const Icon(Icons.attach_file,size:19)),Expanded(child:TextField(controller:input,maxLines:3,minLines:1,textDirection:TextDirection.rtl,decoration:const InputDecoration(hintText:'اكتب رسالتك...',isDense:true))),IconButton(onPressed:sending?null:send,icon:sending?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.send_rounded,size:21))])]))
